public static Stack<Integer> removeBlocks(Stack<Integer> stk) {
    Stack<Integer> result = new Stack<Integer>();
    while (!stk.isEmpty()) {
        int x = stk.pop();
        int count = 1;
        while (!stk.isEmpty() && stk.top() == x) {   // כל הרצף של x
            stk.pop();
            count++;
        }
        if (count == 1) {
            result.push(x);
        }
    }
    return result;
}

