public static String check(Object got, Object expected) {
    String g = String.valueOf(got);
    String e = String.valueOf(expected);
    if (g.equals(e)) {
        return "נכון";
    }
    return "לא נכון — התקבל " + g + ", צריך להתקבל " + e;
}

// הערכים שבמחסנית, ממוינים (כי אין חשיבות לסדר) — בלי לשנות אותה
public static String sorted(Stack<Integer> s) {
    java.util.List<Integer> list = new java.util.ArrayList<Integer>();
    Stack<Integer> temp = new Stack<Integer>();
    while (s != null && !s.isEmpty()) {
        list.add(s.top());
        temp.push(s.pop());
    }
    while (!temp.isEmpty()) {
        s.push(temp.pop());
    }
    java.util.Collections.sort(list);
    return list.toString();
}

