public static Stack<int> RemoveBlocks(Stack<int> stk)
{
    Stack<int> result = new Stack<int>();
    while (!stk.IsEmpty())
    {
        int x = stk.Pop();
        int count = 1;
        while (!stk.IsEmpty() && stk.Top() == x) {   // כל הרצף של x
            stk.Pop();
            count++;
        }
        if (count == 1)
        {
            result.Push(x);
        }
    }
    return result;
}

