    return "לא נכון — התקבל " + g + ", צריך להתקבל " + e;
}

// הערכים שבמחסנית, ממוינים (כי אין חשיבות לסדר) — בלי לשנות אותה
public static string Sorted(Stack<int> s)
{
    System.Collections.Generic.List<int> list = new System.Collections.Generic.List<int>();
    Stack<int> temp = new Stack<int>();
    while (s != null && !s.IsEmpty())
    {
        list.Add(s.Top());
        temp.Push(s.Pop());
    }
    while (!temp.IsEmpty())
    {
        s.Push(temp.Pop());
    }
    list.Sort();
    return "[" + string.Join(", ", list) + "]";
}

